insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('de-schneidarin-hod-drei-klaane-haftln-eigsetzd-damits-klaadl-bessa-sitzd', 'De Schneidarin hod drei klaane Haftln eigsetzd, damits Klaadl bessa sitzd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Schneiderin hat hinten drei kleine Hafteln eingesetzt, damit das Kleid besser sitzt!', '[{"kategorie": "wörtlich", "text": "\"Die Schneiderin hat auf der Rückseite drei kleine Häkchen angenäht, damit das Kleid besser sitzt!\"  2. Mit drei dezenten Verschlusshäkchen am Rücken hat die Schneiderin das Kleid in perfekte Form gebracht!  3. Drei kleine Haken halten das Kleid am Rücken zart zusammen – kaum sichtbar, aber wirkungsvoll!"}]'::jsonb, ''),
  ('aufpassn-wiara-haftlmocha', 'aufpassn wiara Haftlmocha', '', '', '', 'Wiener Sprüche, die sitzen!', 'aufpassen wie ein Haftelmacher', '[{"kategorie": "wörtlich", "text": "\"akribisch genau auf etwas achten\""}, {"kategorie": "", "text": "\"mit scharfem Blick kontrollieren\""}, {"kategorie": "", "text": "\"mit größter Sorgfalt vorgehen\""}, {"kategorie": "", "text": "besonders sorgfältig und genau arbeiten, mit höchster Konzentration und Genauigkeit arbeiten (so wie ein [[Haftelmacher]] [=jemand, der winzige Drahtverschlüsse herstellt])"}]'::jsonb, 'Waunnsd ned aufpasst wiara Haftlmocha, mocht di da Schääf vua olle aundan zua Schneckn!'),
  ('waunnsd-ned-aufpasst-wiara-haftlmocha-mocht-di-da-schaeaef-vua-olle-aundan-zua-schneckn', 'Waunnsd ned aufpasst wiara Haftlmocha, mocht di da Schääf vua olle aundan zua Schneckn!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Wenn du nicht aufpasst wie ein Haftelmacher, macht dich der Chef vor allen anderen zur Schnecke!', '[{"kategorie": "wörtlich", "text": "\"Wenn du nicht äußerst sorgfältig arbeitest, brüllt dich der Chef vor versammelter Mannschaft zusammen!\"  2. Wenn du nicht arbeitest wie unter’m Mikroskop, zerfleischt dich der Alte vor allen Kollegen!  3. Wenn du nicht mit voller Konzentration arbeitest, wirst du vom Chef öffentlich bloßgestellt!"}]'::jsonb, 'aufpassn wiara Haftlmocha'),
  ('i-bin-ma-sicha-dea-haftlmocha-richt-sogoa-de-kloopapiaroin-min-winklmessa-aus', 'I bin ma sicha - dea Haftlmocha richt sogoa de Kloopapiaroin min Winklmessa aus!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'I bin mir sicher - dieser Haftelmacher richtet sogar die Klopapierrolle mit’m Winkelmesser aus!', '[{"kategorie": "wörtlich", "text": "\"I schwör''s, dieser Haftelmacher richtet sogar die Klopapierrolle mit dem Winkelmesser aus!\"  2. Dieser Haftelmacher ist so übertrieben genau, dass er selbst die Klopapierrolle mit dem Winkelmesser ausrichtet!  3. Dieser Haftelmacher kennt keine Gnade - selbst am Klo muss die Rolle millimetergenau hängen!"}]'::jsonb, ''),
  ('aufpassn-wiara-schiasshund', 'aufpassn wiara Schiasshund', '', '', '', 'Wiener Sprüche, die sitzen!', 'aufpassen wie ein Schießhund', '[{"kategorie": "wörtlich", "text": "\"akribisch genau auf etwas achten\""}, {"kategorie": "", "text": "\"mit scharfem Blick kontrollieren\""}, {"kategorie": "", "text": "\"keinen Wimpernschlag verpassen\""}, {"kategorie": "", "text": "\"mit höchster Konzentration und Genauigkeit beobachten\" (so wie ein [[Schießhund]] [=Hund, der dazu abgerichtet ist, bei der Jagd das angeschossene Wild aufzuspüren])"}]'::jsonb, 'De Oide hod aufpassd wiara Schiasshund - dera is kaa aanzigs Wuat entgaungan!'),
  ('de-oide-hod-aufpassd-wiara-schiasshund-dera-is-kaa-aanzigs-wuat-entgaungan', 'De Oide hod aufpassd wiara Schiasshund - dera is kaa aanzigs Wuat entgaungan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Alte hat aufgepasst wie ein Schießhund - der ist kein einziges Wort entgangen!', '[{"kategorie": "wörtlich", "text": "\"Die Alte hat die Ohren gespitzt wie ein Bluthund - der ist kein einziges Wort entgangen!\"  2. Die Alte hat aufgepasst wie ein Spürhund – kein einziges Wort ging ihr durch die Lappen!  3. Die Alte war voll auf Empfang wie ein Schießhund auf Beutezug – kein Mucks ist an ihr vorübergegangen!"}]'::jsonb, 'aufpassn wiara Schiasshund'),
  ('a-haagliche-gschichd', 'a haagliche Gschichd', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine heikliche Geschichte', '[{"kategorie": "wörtlich", "text": "\"eine schwierige Geschichte\""}, {"kategorie": "", "text": "eine delikate Angelegenheit"}, {"kategorie": "", "text": "eine brisante Sache"}, {"kategorie": "", "text": "eine brenzlige Situation"}]'::jsonb, 'Des mid seina Ex is a haagliche Gschichd - do reedta nua ungean driiwa!'),
  ('des-mid-seina-ex-is-a-haagliche-gschichd-do-reedta-nua-ungean-driiwa', 'Des mid seina Ex is a haagliche Gschichd - do reedta nua ungean driiwa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das mit seiner Ex ist eine heikle Geschichte - da redet er nur ungern drüber!', '[{"kategorie": "wörtlich", "text": "\"Das Thema ''Ex-Freundin'' ist für ihn ein sensibles Kapitel – darüber spricht er nicht gern!\"  2. Die Geschichte mit seiner Ex ist kompliziert – da hält er sich lieber bedeckt!  3. Seine frühere Beziehung ist ein delikates Thema - darüber spricht er nur sehr zögerlich!"}]'::jsonb, 'a haagliche Gschichd'),
  ('seids-ned-so-haaglich', 'Seids ned so haaglich!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Seid nicht so heiklich!', '[{"kategorie": "wörtlich", "text": "\"Seid nicht so heikel!\"  2. Seid nicht so empfindlich!  3. Seid nicht so pingelig!  4. Seid nicht so zart besaitet!"}]'::jsonb, ''),
  ('wea-haaglich-is-bleibt-iwa', 'Wea haaglich is, bleibt iwa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wer heiklich ist, bleibt über!', '[{"kategorie": "wörtlich", "text": "\"Wer zart besaitet ist, bleibt über!\"  2. Wer zu pingelig ist, bleibt auf der Strecke!  3. Wer kein dickes Fell hat, wird abgehängt!"}]'::jsonb, ''),
  ('da-schdoff-is-zwoa-nua-hoibseidn-trotzdem-fueuest-di-drin-wiara-keenigin-im-glitzaklaadl', 'Da Schdoff is zwoa nua hoibseidn - trotzdem füüst di drin wiara Keenigin im Glitzaklaadl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Stoff ist zwar nur halbseiden - trotzdem fühlst du dich darin wie eine Königin im Glitzerkleid!', '[{"kategorie": "wörtlich", "text": "\"Der Stoff hat nur einen Hauch Seide – doch du fühlst dich darin wie eine Diva im Glitzerkleid!\"  2. Der Stoff ist zwar nur halbseiden, aber du strahlst darin wie eine Disco-Kugel mit Krone!  3. Der Stoff ist nicht ganz Seide – aber du siehst darin aus wie Beyoncé auf einer Award-Show!"}]'::jsonb, ''),
  ('iagendwos-aun-dem-gschaeft-kummd-ma-hoibseidn-vua-do-moch-i-ned-mit', 'Iagendwos aun dem Gschäft kummd ma hoibseidn vua - do moch I ned mit!', '', '', '', 'Wiener Gaunersprache', 'Irgendwas an diesem Geschäft kommt mir halbseiden vor – da mach ich nicht mit!', '[{"kategorie": "wörtlich", "text": "\"Irgendwas an diesem Geschäft wirkt für mich halbseiden – da spiele ich nicht mit!\"  2. An dem Geschäft ist irgendetwas nicht ganz sauber – da halte ich mich lieber raus!  3. Das ganze Geschäft hat einen zweifelhaften Beigeschmack – da lasse ich lieber die Finger davon!"}]'::jsonb, ''),
  ('waunn-da-hoibseidane-ind-offiziasmess-kummd-faeuds-iwaroi-noch-weiwaparfaeu', 'Waunn da Hoibseidane ind Offiziasmess kummd, fäuds iwaroi noch Weiwaparfäu!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wenn der Halbseidene in die Offiziersmesse kommt, fäult''s überall nach Weiberparfüm!', '[{"kategorie": "wörtlich", "text": "\"Wenn dieser halbseidene Schwule in die Offiziersmesse kommt, stinkt''s überall nach Damenparfüm!\"  2. Wenn dieser parfümierte Schöngeist die Offiziersmesse betritt, glaubt man, man sei im Damenboudoir gelandet!  3. Sobald der schwule Glitzer-General auftaucht, schwebt ein Hauch Lavendel durch die Offiziersmesse!"}]'::jsonb, ''),
  ('si-is-a-hoibseidane-tuad-owa-auf-soseijati-lejdi', 'Si is a Hoibseidane, tuad owa auf Soseijati-Lejdi!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Sie ist eine Halbseidene, tut aber auf Society-Lady!', '[{"kategorie": "wörtlich", "text": "\"Sie ist eine Dame der Halbwelt, tut aber auf Society-Lady!\"  2. Sie kommt aus der Halbwelt, spielt aber die Grande Dame!  3. Sie ist mehr Bordstein als Ballsaal, aber gibt sich wie Gräfin Glimmerlicht!"}]'::jsonb, ''),
  ('a-wiina-kaffeehauskoeoena-muass-es-weisse-hangal-imma-akkurat-iwan-linkn-oam-liing-haengan-so-wia-sis-ghead', 'A Wiina Kaffeehauskööna muass es weisse Hangal imma akkurat iwan linkn Oam liing hängan - so wia sis ghead!', '', '', '', 'Wiener Kaffeehaus-ABC', 'Ein Wiener Kaffeehauskellner muss das weiße Hangerl immer akkurat über dem linken Arm hängen haben - so wie sich''s gehört!', '[{"kategorie": "wörtlich", "text": "\"Ein Wiener Kaffeehauskellner muss das weiße Serviertuch immer akkurat über dem linken Arm hängen haben - so wie sich''s gehört!\"  2. Ein Wiener Kaffeehauskellner trägt sein weißes Serviertuch stets ordentlich über dem linken Arm – das gehört zum guten Ton!  3. Ein gepflegter Wiener Kaffeehauskellner hat sein Serviertuch immer sauber und gefaltet über dem linken Arm – wie es die Tradition verlangt!"}]'::jsonb, ''),
  ('bind-unsan-bauxal-es-hangal-um-waeu-heit-gibds-paradeis-sooss', 'Bind unsan Bauxal es Hangal um - wäu heit gibds Paradeis-Sooss!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Binde unserem Bauxerl das Hangerl um - weil heute gibt''s Paradeissoße!', '[{"kategorie": "wörtlich", "text": "\"Binde unserem Knirps das Sabbertuch um - denn heute gibt''s Tomatensauce!\"  2. Mach unserem Kleinen bitte das Lätzchen um – heute gibt’s Tomatensoße!  3. Lege dem Kind den Brustlatz an – es gibt rote Soße, und die kennt keine Gnade!"}]'::jsonb, ''),
  ('schnoeoe-gimmas-hangal-i-muass-iwan-head-driiwawischn-do-is-wos-iwaglaufn', 'Schnöö, gimmas Hangal - I muass iwan Head driiwawischn, do is wos iwaglaufn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Schnell, gib mir das Hangerl - ich muss über den Herd drüberwischen, da ist was übergelaufen!', '[{"kategorie": "wörtlich", "text": "\"Schnell, gib mir das Wischtuch - ich muss über den Herd drüberwischen, da ist was übergelaufen!\"  2. Gib mir bitte schnell das Tuch – auf dem Herd ist was übergelaufen, ich muss kurz drüberwischen!  3. Da ist was übergekocht – ich brauch schnell ein Tuch, um den Herd zu wischen!"}]'::jsonb, ''),
  ('gimmas-gschiahangal-i-trockn-scho-moi-de-toella-oo', 'Gimmas Gschiahangal - I trockn scho moi de Tölla oo!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Gib mir das Geschirrhangerl - ich trockne schon mal die Teller ab!', '[{"kategorie": "wörtlich", "text": "\"Gib mir bitte das Geschirrtuch - ich fang schon mal an, die Teller trocken zu wischen!\"  2. Reich mir das Trockentuch – ich mach mich schon mal an die Teller ran!  3. Hol mir schnell das Abtrockentuch, dann wisch ich gleich mal die Teller trocken!"}]'::jsonb, ''),
  ('woama-hansl', 'Woama Hansl', 'der', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Warmer Hansel', '[{"kategorie": "wörtlich", "text": "\"warm und schal gewordener Rest im Bierglas\" (von [[Hansl]]=\"abgestandener Bierrest\")"}, {"kategorie": "scherzhaft für", "text": "\"lauwarmer Bierrest ohne Kohlensäure\", \"abgestandener, schaler Bierrest im Glas\", [[Fenstaschwitz]], [[Offnbrunzlad]], [[Lack]], [[Bialack]]"}]'::jsonb, 'Im Biaglaasl woa nua no a woama Hansl - und dea woa fost schoo vadaumpfd!'),
  ('im-biaglaasl-woa-nua-no-a-woama-hansl-und-dea-woa-fost-schoo-vadaumpfd', 'Im Biaglaasl woa nua no a woama Hansl - und dea woa fost schoo vadaumpfd!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Im Bierglas war nur noch ein warmer Hansl - und der war fast schon verdampft!', '[{"kategorie": "wörtlich", "text": "\"Im Bierglas war nur noch ein letzter, abgestandener Rest - und der war fast schon verdampft!\"  2. Im Glas war nur noch ein winziger, schal gewordener Schluck Bier – und der war fast schon verdampft!  3. Nur ein lauwarmer Rest war im Glas noch übrig – ohne Kohlensäure, kaum noch Bier zu nennen!"}]'::jsonb, 'Woama Hansl'),
  ('i-hob-im-goatn-no-zwaa-frische-happaen-solood-de-kumman-heit-ind-schissl', 'I hob im Goatn no zwaa frische Happän Solood - de kumman heit ind Schissl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich hab im Garten noch zwei frische Häuptel Salat – die kommen heut in die Schüssel!', '[{"kategorie": "wörtlich", "text": "\"Ich habe im Garten noch zwei frische Salatköpfe – die kommen heute auf den Tisch!\"  2. Die letzten zwei Salatköpfe aus dem Garten kommen heute direkt in die Schüssel!  3. Die Häuptel im Garten sind reif – heute gibt’s frischen Blattsalat direkt vom Beet!"}]'::jsonb, ''),
  ('aane-aufs-happae-kriang', 'aane aufs Happä kriang', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine aufs Happel kriegen!', '[{"kategorie": "wörtlich", "text": "\"eine aufs Häuptel kriegen\",  \"einen Schlag auf den Kopf bekommen\", \"eine auf die Nuss kriegen\", \"eine drübergebraten kriegen\""}, {"kategorie": "fig.", "text": "\"eine aufs Dach bekommen\", \"eine Abreibung bekommen\", \"einen Rüffel kassieren\", \"den Kopf gewaschen bekommen\""}]'::jsonb, 'Waunn dea no amoi so blääd daheareed, kriagda aane aufs Happä!'),
  ('waunn-dea-no-amoi-so-blaeaed-daheareed-kriagda-aane-aufs-happae', 'Waunn dea no amoi so blääd daheareed, kriagda aane aufs Happä!', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Wenn der noch einmal so blöd daherredet, kriegt er eine aufs Haupt!', '[{"kategorie": "wörtlich", "text": "\"Wenn der noch einmal so blöd daherredet, kriegt er eine aufs Dach!\"  2. Wenn der noch einmal die Klappe so aufreißt, gibt’s eins auf die Mütze!  3. Wenn der nochmal so klugscheißert, kriegt er den Kopf gewaschen!"}]'::jsonb, 'aane aufs Happä kriang'),
  ('ea-hod-aane-aufs-happae-kriagd-waeura-de-frist-vasaamd-hod', 'Ea hod aane aufs Happä kriagd, wäura de Frist vasaamd hod!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Er hat eine aufs Haupt gekriegt, weil er die Frist versäumt hat!', '[{"kategorie": "wörtlich", "text": "\"Er hat ordentlich eine aufs Dach bekommen, weil er die Frist verpasst hat!\"  2. Wegen der Fristversäumnis hat er einen ordentlichen Rüffel kassiert!  3. Er hat eine ordentliche Klatsche gekriegt, weil er den Termin vergeigt hat!"}]'::jsonb, 'aane aufs Happä kriang'),
  ('schneids-soloodhappae-in-feine-schdraafn-und-gib-a-poa-klaane-paradeisa-dazua', 'Schneids Soloodhappä in feine Schdraafn und gib a poa klaane Paradeisa dazua!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Schneide das Salathäuptel in feine Streifen und gib ein paar kleine Paradeiser dazu!', '[{"kategorie": "wörtlich", "text": "\"Schneide den Kopfsalat in feine Streifen und gib ein paar kleine Tomaten dazu!\"  2. Den Salat in Streifen schneiden und mit Kirschtomaten vermengen!  3. Schnapp dir den Salatkopf, schneid ihn klein und wirf ein paar Tomätchen rein!"}]'::jsonb, ''),
  ('zupf-in-happaesolood-in-grobe-blaadln-und-marinia-eam-mit-balsamico', 'Zupf in Happäsolood in grobe Blaadln und marinia eam mit Balsamico!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Zupfe den Häuptelsalat in grobe Blätter und mariniere ihn mit Balsamico!', '[{"kategorie": "wörtlich", "text": "\"Zupfe den Kopfsalat in grobe Blätter und mariniere ihn mit Balsamico!\"  2. Zerteile den Kopfsalat in größere Blätter und beträufle ihn mit Balsamico!  3. Kopfsalatblätter locker in Stücke reißen, anschließend behutsam mit Balsamico marinieren!"}]'::jsonb, ''),
  ('i-hob-zwa-haabe-roppn', 'I hob zwa haabe Roppn!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Ich hab zwei harbe Rappen!', '[{"kategorie": "wörtlich", "text": "\"Ich habe zwei lebhafte Rappen!\"  2. Ich habe zwei temperamentvolle, schwarze Pferde!  3. Meine zwei Rappen haben Feuer im Hintern!"}]'::jsonb, ''),
  ('zua-tauf-hod-ma-mei-goodl-a-sueuewanes-kreiz-gschenkd', 'Zua Tauf hod ma mei Goodl a süüwanes Kreiz gschenkd!', '', '', '', 'Religiöses & Göttliches auf Wienerisch', 'Zur Taufe hat mir meine God''l ein silbernes Kreuz geschenkt!', '[{"kategorie": "wörtlich", "text": "\"Zur Taufe hat mir meine Patin ein silbernes Kreuz geschenkt!\"  2. \"Von meiner Patentante habe ich zur Taufe ein silbernes Kreuz bekommen!\"  3. \"Ein silbernes Kreuz war das Taufgeschenk meiner Patin!\""}]'::jsonb, ''),
  ('des-is-a-haabe-goodl', 'Des is a haabe Goodl!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Das ist eine harbe Godel!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein [[resches]] Weib!\"  2. Das ist ein resolutes Frauenzimmer!  3. Das ist ein temperamentvolles Mädel!"}]'::jsonb, ''),
  ('zeig-s-da-goodl', 'Zeig''s da Goodl!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zeig''s der Godl!', '[{"kategorie": "wörtlich", "text": "\"Zeig''s dem schnippischen Weibsbild!\"  2. Zeig''s dem Frauenzimmer!  3. Gib dem resoluten Weib mal ordentlich Kontra!"}]'::jsonb, ''),
  ('sei-bitte-ned-haab-auf-mi', 'Sei bitte ned haab auf mi!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Sei bitte nicht harb auf mich!', '[{"kategorie": "wörtlich", "text": "\"Bitte sei mir nicht gram!\"  2. Sei bitte nicht böse auf mich!  3.Bitte sei nicht sauer auf mich!"}]'::jsonb, ''),
  ('kumm-hea-du-oams-haschal-du-bist-jo-gaunz-duachgfruan', 'Kumm hea, du oams Haschal - du bist jo gaunz duachgfruan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm her, du armes Hascherl - du bist ja ganz durchgefroren!', '[{"kategorie": "wörtlich", "text": "\"Komm her, du armes Seelchen, du bist ja ganz durchgefroren!\"  2. Komm her, du armes Würmchen – du bist ja ganz steif vor Kälte!  3. Komm her, mein armes Herzchen – du bist ja halb erfroren!"}]'::jsonb, ''),
  ('si-schbueueds-oame-haschal-dabei-is-ollas-aundare-ois-hueueflos', 'Si schbüüds oame Haschal - dabei is ollas aundare ois hüüflos!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie spielt das arme Hascherl - dabei ist sie alles andere als hilflos!', '[{"kategorie": "wörtlich", "text": "\"Sie tut so, als wäre sie ein armes Würstchen – dabei weiß sie genau, was sie will!\"  2. Sie mimt die Hilflose – dabei hat sie die Fäden fest in der Hand!  3. Sie spielt das schwache Rehlein - dabei hat sie Zähne wie ein Wolf!"}]'::jsonb, ''),
  ('wia-san-duachn-kniahoochn-schnaeae-ghaascht-dass-de-waadln-brennd-haum', 'Wia san duachn kniahoochn Schnää ghaascht, dass de Waadln brennd haum!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wir sind durch den kniehohen Schnee gehatscht, dass die Wadeln gebrannt haben!', '[{"kategorie": "wörtlich", "text": "\"Wir sind durch kniehohen Schnee gestapft, bis die Waden brannten!\"  2. Wir sind durch den Schnee gepflügt wie zwei alte Ochsen – und die Wadeln haben gebrannt wie Feuer!  3. Wir wateten durch kniehohen Schnee - und jeder Schritt brannte mächtig in den Waden!"}]'::jsonb, ''),
  ('seita-a-breezn-grissn-hod-haaschta-owa-es-wiad-laungsaum-bessa', 'Seita a Breezn grissn hod, haaschta - owa es wiad laungsaum bessa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seit er eine Brezen gerissen hat, hatscht er - aber es wird langsam besser!', '[{"kategorie": "wörtlich", "text": "\"Seit seinem Sturz hinkt er - aber es wird langsam besser!\"  2. Er hinkt seit dem Unfall, aber mit der Zeit wird’s besser!  3. Seit dem Hinfaller lahmt er noch ein bisschen – aber es wird von Tag zu Tag besser!"}]'::jsonb, ''),
  ('seine-oidn-haatschn-quiitschn-bei-an-jeedn-schriad-so-ois-daedns-glei-ausanaundafoin', 'Seine oidn Haatschn quiitschn bei an jeedn Schriad - so ois dädns glei ausanaundafoin!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Seine alten Hatschen quietschen bei jedem Schritt - so als würden sie gleich auseinanderfallen!', '[{"kategorie": "wörtlich", "text": "\"Seine alten, ausgetretenen Schuhe quietschen bei jedem Schritt - so als würden sie gleich auseinanderfallen!\"  2. Seine alten Latschen quietschen, als würden sie gleich ihren Dienst quittieren!  3. Seine abgetragenen Schuhe knarzen bei jedem Schritt – so als würden sie gleich den Geist aufgeben!"}]'::jsonb, ''),
  ('de-oide-haatschn-kriagd-si-aa-nimma-jinga-gschminkd', 'De oide Haatschn kriagd si aa nimma jinga gschminkd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Die alte Hatschen kriegt sich auch nimmer jünger geschminkt!', '[{"kategorie": "wörtlich", "text": "\"Die abgetakelte Alte kriegt sich auch nimmer jünger geschminkt!\"  2. Die alte Schlampe kann sich schminken so viel sie will – jünger wird sie dadurch auch nicht!  3. Der alte Wanderpokal versucht, jugendlich zu wirken – aber ihre vielen Männerbekanntschaften lassen sich nicht so einfach wegschminken!"}]'::jsonb, ''),
  ('jetzt-oaweid-de-haatschn-im-laufhaus-und-hod-mea-kundschofd-ois-de-trafik-daneem', 'Jetzt oaweid de Haatschn im Laufhaus - und hod mea Kundschofd ois de Trafik daneem!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Jetzt arbeitet die Hatschen im Laufhaus - und hat mehr Kundschaft als die Trafik daneben!', '[{"kategorie": "wörtlich", "text": "\"Jetzt arbeitet die Schlampe im Laufhaus - und hat mehr Kundschaft als die Trafik daneben!\"  2. Jetzt arbeitet die Bordsteinschwalbe im Puff - und verdient dort mehr als je zuvor!  3. Jetzt verdient das Luder im Freudenhaus ihr Geld – und hat mehr Kundschaft als unser Würstelstand!"}]'::jsonb, ''),
  ('noch-dem-haatschara-brauch-i-neiche-fiass', 'Noch dem Haatschara brauch I neiche Fiaß!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Nach dem Hatscherer brauche ich neue Füße!', '[{"kategorie": "wörtlich", "text": "\"Nach diesem Gewaltmarsch brauche ich neue Beine!\"  2. (scherzhaft für): Nach dieser brutal langen Wanderung sind meine Beine reif für die Schrottpresse!\"  3. Nach dieser endlos langen Tortur zu Fuß brauch ich vier Räder oder zwei neue Beine!"}]'::jsonb, ''),
  ('noch-dem-haatscha-brauch-i-neiche-fiass', 'Noch dem Haatscha brauch I neiche Fiaß!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Nach dem Hatscher brauche ich neue Füße!', '[{"kategorie": "wörtlich", "text": "\"Nach diesem Gewaltmarsch brauche ich neue Beine!\"  2. (scherzhaft für): Nach dieser brutal langen Wanderung sind meine Beine reif für die Schrottpresse!\"  3. Nach dieser endlos langen Tortur zu Fuß brauch ich vier Räder oder zwei neue Beine!"}]'::jsonb, ''),
  ('wechslds-in-haatschadn-aus-bevuara-no-umfoid', 'Wechslds in Haatschadn aus, bevuara no umfoid!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Wechselt den Hatscherten aus, bevor er noch umfällt!', '[{"kategorie": "wörtlich", "text": "\"Wechselt den Humpelbeinigen aus, bevor er noch umfällt!\"  2. Nehmt den Lahmen vom Feld - der fällt gleich auseinander!  3. Der eine Spieler hinkt, als hätte er ein Holzbein - wann wird er endlich ausgetauscht?"}]'::jsonb, ''),
  ('do-iwahoid-da-haatschade-in-hinkadn', 'Do iwahoid da Haatschade in Hinkadn!', '', '', '', 'Wiener Mechaniker-Slang', 'Da überholt der Hatscherte den Hinkenden!', '[{"kategorie": "wörtlich", "text": "\"Da überholt der Humpelnde den Hinkenden!\" (scherzhaft zur Beschreibung eines endlos langen Überholmanövers bzw. \"Elefantenrennens auf der Autobahn\", bei dem ein LKW-Fahrer - trotz nur geringem Geschwindigkeitsüberschuss - einen anderen LKW zu überholen versucht)"}, {"kategorie": "", "text": "\"Da überholt der lahme 40-Tonner den müden 38-Tonner!\"  3. Da keucht der eine Koloss am anderen vorbei – Millimeter pro Stunde!"}]'::jsonb, ''),
