  ('s-haxal-heem', 's''Haxal heem', '', '', '', 'Wiener Sprüche, die sitzen!', 'das Haxerl heben', '[{"kategorie": "", "text": "\"das Hinterbein heben\""}, {"kategorie": "", "text": "\"Pipi machen\""}]'::jsonb, 'Mei Hund hebd bei aana jeedn Latean s''Haxal - 10 Meeta in 5 Minuutn!'),
  ('s-haxl-heem', 's''Haxl heem', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'das Haxl heben', '[{"kategorie": "", "text": "\"das Hinterbein heben\""}, {"kategorie": "", "text": "\"Pipi machen\""}]'::jsonb, 'Mei Hund hebd bei aana jeedn Latean s''Haxl - 10 Meeta in 5 Minuutn!'),
  ('mei-hund-hebd-bei-aana-jeedn-latean-s-haxal-10-meeta-in-5-minuutn', 'Mei Hund hebd bei aana jeedn Latean s''Haxal - 10 Meeta in 5 Minuutn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Mein Hund hebt bei jeder Laterne das Haxerl - 10 Meter in 5 Minuten!', '[{"kategorie": "wörtlich", "text": "\"Mein Hund hebt bei jeder Laterne das Beinchen - 10 Meter in 5 Minuten!\"  2. Mein Hund bleibt bei jeder Laterne stehen, um sein Hinterbein zu heben – wir kommen kaum vorwärts!  3. Wenn’s nach meinem Hund geht, markieren wir jede Laterne in unserem Gemeindebau!"}]'::jsonb, 's''Haxal heem'),
  ('mei-hund-hebd-bei-aana-jeedn-latean-s-haxl-10-meeta-in-5-minuutn', 'Mei Hund hebd bei aana jeedn Latean s''Haxl - 10 Meeta in 5 Minuutn!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Mein Hund hebt bei jeder Laterne das Haxl - 10 Meter in 5 Minuten!', '[{"kategorie": "wörtlich", "text": "\"Mein Hund hebt bei jeder Laterne das Beinchen - 10 Meter in 5 Minuten!\"  2. Mein Hund bleibt bei jeder Laterne stehen, um sein Hinterbein zu heben – wir kommen kaum vorwärts!  3. Wenn’s nach meinem Hund geht, markieren wir jede Laterne in unserem Gemeindebau!"}]'::jsonb, 's''Haxl heem'),
  ('wem-ins-haxl-beissn', 'wem ins Haxl beissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem ins Haxel beißen', '[{"kategorie": "wörtlich", "text": "\"jemandem in den Rücken fallen\""}, {"kategorie": "", "text": "\"jemandem hintenrum in die Parade fahren\""}, {"kategorie": "", "text": "\"jemandem das Messer in den Rücken rammen\""}, {"kategorie": "", "text": "\"jemanden aus dem Hinterhalt attackieren\""}, {"kategorie": "", "text": "jemandem ans Bein pinkeln"}]'::jsonb, 'Kaum host a bissl aan Eafoig, beissda aa schoo wea ins Haxl - owa Oobocht, I beiss zruck!'),
  ('kaum-host-a-bissl-aan-eafoig-beissda-aa-schoo-wea-ins-haxl-owa-oobocht-i-beiss-zruck', 'Kaum host a bissl aan Eafoig, beissda aa schoo wea ins Haxl - owa Oobocht, I beiss zruck!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kaum hast du ein bisschen Erfolg, beißt dir auch schon wer ins Haxel - aber Obacht, ich beiße zurück!', '[{"kategorie": "wörtlich", "text": "\"Kaum läuft’s mal gut, kommt garantiert einer, der dir hintenrum in die Parade fährt – aber ich weiß mich zu wehren!\"  2. Kaum läuft’s, pinkelt dir einer ans Bein – aber Achtung, ich pinkel zurück. Und zwar treffsicher!  3. Du schaffst was – und schon beißt dich irgendein Kleingeist ins Haxel - aber Vorsicht, ich beiße zurück!"}]'::jsonb, 'wem ins Haxl beissn'),
  ('hean-s', 'Hean''S!', '', '', '', 'Grundwortschatz Wienerisch', 'Hören''S!', '[{"kategorie": "wörtlich", "text": "\"Hören Sie!\" (Anrede / Interjektion – verwendet wie ein Ruf, ähnlich wie „Sie da!“ oder „Hey!“)"}, {"kategorie": "", "text": "\"Hören Sie mal!\" 3. Sagen Sie mal! (Ausrufewort, meist am Anfang eines Satzes, womit man seine Empörung oder eine dringende Aufforderung ausdrückt)"}, {"kategorie": "", "text": "Mensch!"}, {"kategorie": "", "text": "Verdammt!  6. Los, machen Sie schon!"}]'::jsonb, ''),
  ('hean-s-san-s-deppad', 'Hean''S, san''S deppad?', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hören Sie, sind Sie deppert?', '[{"kategorie": "wörtlich", "text": "\"Hey, Sie da! Sind Sie noch ganz bei Trost?\"  2. Hören Sie mal! Geht''s noch bei Ihnen?  3. Sagen Sie mal, ticken Sie noch richtig?"}]'::jsonb, ''),
  ('san-s-zwaa-oda-wos', 'San''s zwaa oda wos?', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sind Sie zwei oder was?', '[{"kategorie": "wörtlich", "text": "\"Was soll das? Sind Sie zwei oder wollen Sie nur so wirken?\"  2. Müssen Sie sich allein so breit machen wie zwei ?\"  3. Sie stehen im Weg!  4. Machen Sie Platz!"}]'::jsonb, 'Hean''S, Si dearische Kapöön! San''S zwaa oda wos?'),
  ('hean-s-si-dearische-kapoeoen-san-s-zwaa-oda-wos', 'Hean''S, Si dearische Kapöön! San''S zwaa oda wos?', '', '', '', 'Schimpfen und Fluchen auf Wienerisch', 'Hey, Sie törische Kapelle! Sind Sie zwei oder was?', '[{"kategorie": "wörtlich", "text": "\"Hey, Sie taube Nuss! Sind Sie zwei oder wollen Sie nur so wirken?\"  2. Hey, Sie taube Wand! Können Sie mal Platz machen?  3. Verdammt, machen Sie sich nicht so breit wie zwei! Lassen Sie die Leute vorbei!"}]'::jsonb, 'San''s zwaa oda wos?'),
  ('des-geed-si-aus', 'Des geed si aus!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das geht sich aus!', '[{"kategorie": "wörtlich", "text": "\"Das reicht schon noch!\"  2. Das passt schon!  3. Das ist machbar!  4. Das geht sich terminlich / mengenmäßig / finanziell / organisatorisch schon noch aus!  5. Das wird sich schon fügen!  6. Das wird schon hinhauen! (Im Standarddeutschen gibt es für diese Phrase kein direktes 1:1-Äquivalent, aber viele sinngleiche Umschreibungen und Synonyme, je nach Kontext. Konkret handelt es sich um einen Bohemismus bzw. um die wortwörtliche Übersetzung des tschechischen \"to vyjde\"=\"Das geht sich aus\" [vom tschechischen Verb \"vyjít\"=\"ausgehen\")"}]'::jsonb, 'Glaubsd, des geed si aus, dass I ned in Bau kumm?'),
  ('glaubsd-des-geed-si-aus-dass-i-ned-in-bau-kumm', 'Glaubsd, des geed si aus, dass I ned in Bau kumm?', '', '', '', 'Wiener Gaunersprache', 'Glaubst du, das geht sich aus, dass ich nicht in den Bau komme?', '[{"kategorie": "wörtlich", "text": "\"Meinst du, ich komm da noch raus, ohne eingesperrt zu werden?\"  2. Denkst du, da ist noch Spielraum, oder bin ich geliefert?  3. Glaubst du, ich krieg noch die Kurve, oder ist mir der [[Häfen]] schon sicher?"}]'::jsonb, 'Des geed si aus!'),
  ('des-geed-si-ned-aus', 'Des geed si ned aus!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das geht sich nicht aus!', '[{"kategorie": "wörtlich", "text": "\"Das reicht wohl nicht!\"  2. Daraus wird wohl nichts!  3. Das wird wohl nicht klappen!  4. Das wird wohl nicht hinhauen!  5. Das wird sich terminlich / mengenmäßig / finanziell / organisatorisch wohl nicht ausgehen!  (Im Standarddeutschen gibt es für diese Phrase kein direktes 1:1-Äquivalent, aber viele sinngleiche Umschreibungen und Synonyme, je nach Kontext. Konkret handelt es sich um einen Bohemismus bzw. um die wortwörtliche Übersetzung des tschechischen \"to nevyjde\"=\"Das geht sich nicht aus\" [vom tschechischen Verb \"vyjít\"=\"ausgehen\")"}]'::jsonb, 'Wos de freie Schdöö betriffd, wiad si des fia eam ned gaunz ausgee!'),
  ('wos-de-freie-schdoeoe-betriffd-wiad-si-des-fia-eam-ned-gaunz-ausgee', 'Wos de freie Schdöö betriffd, wiad si des fia eam ned gaunz ausgee!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Was die freie Stelle betrifft, wird es sich für ihn nicht ganz ausgehen!', '[{"kategorie": "wörtlich", "text": "\"Was die freie Stelle betrifft, wird es für ihn wohl nicht ganz reichen!\"  2. Für ihn wird''s wohl nix mit der freien Stelle!  3. Für den Job wird’s bei ihm wohl nicht ganz hinhauen!"}]'::jsonb, 'Des geed si ned aus!'),
  ('wem-min-nossn-fetzn-vajaukn', 'wem min nossn Fetzn vajaukn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemanden mit dem nassen Fetzen verjagen', '[{"kategorie": "wörtlich", "text": "\"jemanden mit Schimpf und Schande davonscheuchen\""}, {"kategorie": "", "text": "\"jemanden mit einem Arschtritt zum Teufel jagen\""}, {"kategorie": "", "text": "\"jemanden wie den letzten Dreck rausprügeln\""}, {"kategorie": "", "text": "\"jemanden mit Pauken und Trompeten rauswerfen\""}]'::jsonb, 'Si haum eam ned nua asseghaud - si haum eam min nossn Fetzn vajaukd!'),
  ('si-haum-eam-ned-nua-asseghaud-si-haum-eam-min-nossn-fetzn-vajaukd', 'Si haum eam ned nua asseghaud - si haum eam min nossn Fetzn vajaukd!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Sie haben ihn nicht nur rausgeworfen - sie haben ihn mit dem nassen Fetzen verjagt!', '[{"kategorie": "wörtlich", "text": "\"Er wurde nicht nur entlassen - er wurde mit Schimpf und Schande davongescheucht!\"  2. Er wurde nicht einfach entlassen – man hat ihn mit einem Arschtritt zum Teufel gejagt!  3. Das war keine Kündigung - das war ein Rauswurf mit Pauken und Trompeten!"}]'::jsonb, 'wem min nossn Fetzn vajaukn'),
  ('zum-haekln-brauchsd-nua-a-haeklnoodl-und-a-woikneil', 'Zum Häkln brauchsd nua a Häklnoodl und a Woikneil!"', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Zum Häkeln brauchst du nur eine Häkelnadel und ein Wollknäuel!', '[{"kategorie": "wörtlich", "text": "\"Zum Häkeln brauchst du nur eine Häkelnadel und ein Knäuel Garn!\"  2. Zum Häkeln brauchst du nur drei Dinge: eine Häkelnadel, einen Faden und ein bisschen Geduld ! 3. Alles, was du zum Häkeln brauchst, ist eine Häkelnadel und ein Knäuel Garn!"}]'::jsonb, ''),
  ('fia-a-koanetto-heidlbea-gib-i-meinen-beidl-hea', 'Fia a Koanetto Heidlbea gib I meinen Beidl hea!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Für ein Cornetto Heidelbeer geb ich meinen Beidl her!', '[{"kategorie": "wörtlich", "text": "\"Für ein Cornetto Heidelbeer geb ich meinen Pimmel her!\" (Scherzreim, \"Cornetto\"=Produktname des einstigen Stanitzleises der Firma Eskimo)"}, {"kategorie": "", "text": "\"Für ein Cornetto Heidelbeer geb ich glatt mein [[Zumpferl]] her!\"  3. Cornetto zart mit Heidelbeer – dafür gäbe ich mein [[Spatzerl]] her!"}]'::jsonb, ''),
  ('des-is-ma-heidl', 'Des is ma Heidl!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist mir Heidel!', '[{"kategorie": "wörtlich", "text": "\"Das ist mir Häutel!\"  2. Das ist mir egal!  3. [[Das]] ist mir wurscht!  4. Das ist mir [[Powidl]]!  5. Das ist mir [[Blunzen]]!  6. Das ist mir [[schezkojedno]]!"}]'::jsonb, ''),
  ('des-is-ma-heidlbea', 'Des is ma Heidlbea!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das ist mir Heidelbeere!', '[{"kategorie": "wörtlich", "text": "\"Das ist mir so schnurz wie eine Heidelbeere!\"  2. \"Das ist mir egal!\"  3. [[Das]] ist mir wurscht!  4. Das ist mir [[Powidl]]!  5. Das ist mir [[Blunzen]]!  6. Das ist mir [[schezkojedno]]!"}]'::jsonb, ''),
  ('des-kaunnst-heidln', 'Des kaunnst heidln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das kannst du heideln!', '[{"kategorie": "wörtlich", "text": "\"Das kannst du häuteln!\"  2. Das kannst du dir abschminken!\"  3. \"Das kannst du vergessen!\"  4. \"Das kannst du dir aus dem Kopf schlagen!\""}]'::jsonb, ''),
  ('heidschi-mochn', 'heidschi mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'Heidschi machen', '[{"kategorie": "wörtlich, Kindersprache", "text": "\"ein Schläfchen machen\""}, {"kategorie": "", "text": "\"ein Nickerchen machen\""}, {"kategorie": "", "text": "\"sich aufs Ohr legen\""}, {"kategorie": "", "text": "[[Heija machen]]"}, {"kategorie": "", "text": "[[Heidi-Bubu machen]]"}]'::jsonb, ''),
