  ('heidschi-bumbeidschi', 'Heidschi-Bumbeidschi', 'das', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Heidschi-Bumbeidschi', '[{"kategorie": "wörtlich", "text": "\"Bübchen schlaf ein!\"  (Titel eines traditionellen Wiegenlieds, das ein Kind mit sanften, lautmalerischen Klängen („Heidschi“, „Bumbeidschi“) beruhigen und in den Schlaf begleiten soll. Es gehört zu den bekanntesten Volks- und Weihnachtsliedern im deutschsprachigen Raum und wurde vielfach vertont)"}, {"kategorie": "", "text": "\"Schlaf, mein Bübchen, schlaf!\"  3. Schlaf ein, mein Junge, schlaf ein!"}]'::jsonb, ''),
  ('mit-wem-ind-heija-hupfn', 'mit wem ind Heija hupfn', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'mit jemandem in die Heija hüpfen', '[{"kategorie": "wörtlich", "text": "\"mit jemandem ins Bett gehen\""}, {"kategorie": "", "text": "\"mit jemandem den Beischlaf vollziehen\""}, {"kategorie": "", "text": "\"mit jemandem Sex haben\""}]'::jsonb, 'Gemma ind Heija!'),
